#[cfg(test)]
mod tests {
    use std::{
        collections::VecDeque,
        path::Path,
        sync::{Arc, Mutex},
    };

    use callisto_model::{CommandError, CommandRunner};

    use super::*;

    #[derive(Clone, Default)]
    struct RecordingRunner {
        calls: Arc<Mutex<Vec<(String, Vec<String>)>>>,
        outputs: Arc<Mutex<VecDeque<Result<CommandOutput, CommandError>>>>,
    }

    impl CommandRunner for RecordingRunner {
        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            self.calls.lock().unwrap().push((
                program.to_string(),
                args.iter().map(|value| value.to_string()).collect(),
            ));
            self.outputs.lock().unwrap().pop_front().unwrap()
        }
    }

    fn output(exit_code: i32, stdout: &str, stderr: &str) -> Result<CommandOutput, CommandError> {
        Ok(CommandOutput {
            exit_code: Some(exit_code),
            stdout: stdout.to_string(),
            stderr: stderr.to_string(),
        })
    }

    #[test]
    fn github_parser_accepts_real_nonzero_404_response_without_accepting_bare_error_text() {
        let response = CommandOutput {
            exit_code: Some(1),
            stdout: "HTTP/2 404 Not Found\r\ncontent-type: application/json\r\n\r\n{\"message\":\"Not Found\"}".into(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&response).map(|(status, _)| status), Some(404));
        let bare = CommandOutput {
            exit_code: Some(1),
            stdout: String::new(),
            stderr: "gh: Not Found (HTTP 404)".into(),
        };
        assert_eq!(parse_http_response(&bare), None);

