        // upstream by `is_valid_git_ref_name`, but defended here too) can
        // never be misread as a `git tag` flag even if it started with `-`.
        let canonical_message = message.map(canonical_tag_annotation_message);
        let mut args: Vec<&str> = vec!["tag"];
        if let Some(msg) = canonical_message.as_deref() {
            // Unlike the default `git tag -m` cleanup, this preserves the
            // shared canonical bytes used by native gix tag creation.
            args.extend(["-a", "--cleanup=verbatim", "-m", msg]);
